let state={data:null,rows:[]};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,n=2)=>Number.isFinite(x)?x.toFixed(n):'undefined';
function renderTrail(){const filter=document.querySelector('#status').value;const ex=state.data.ledger.experiments.filter(x=>filter==='all'||x.status===filter);document.querySelector('#trail').innerHTML=ex.map(x=>`<article class="experiment"><div class="label">${esc(x.label)}</div><div><h3><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)} ↗</a></h3><p><strong>Hypothesis.</strong> ${esc(x.hypothesis)}</p>${x.observation?`<p><strong>Observed.</strong> ${esc(x.observation)}</p>`:''}<details><summary>Method, conditions & decision rule</summary><p>${esc(x.method)}</p><p>${esc(x.success_criteria)}</p>${x.result_file?`<a href="${esc(x.result_file)}" download>Download full aggregate result ↓</a>`:''}</details></div><div class="status"><span class="badge">${esc(x.status)}</span>${x.outcome?`<p>${esc(x.outcome.replaceAll('_',' '))}</p>`:''}</div></article>`).join('')||'<p class="empty-note">No experiments match this filter.</p>';}
function renderRows(){let rows=state.rows;const filter=document.querySelector('#stage').value;if(filter!=='all')rows=rows.filter(x=>x.stage===filter);document.querySelector('#models').innerHTML=rows.map(x=>`<tr class="${x.selected?'selected':''}"><td>${esc(x.model)}${x.selected?' · validation selected':''}</td><td>${fmt(x.metrics.rmse)}</td><td>${fmt(x.metrics.r,3)}</td><td>${fmt(x.metrics.chi2)}</td><td>${fmt(x.metrics.hse_ts,3)}</td><td>${fmt(x.metrics.mae)}</td></tr>`).join('');const metric=document.querySelector('#metric').value;const vals=rows.filter(x=>Number.isFinite(x.metrics[metric]));if(!vals.length){document.querySelector('#plot').innerHTML='';return;}const descending=["r","hse_ts"].includes(metric);const shown=vals.slice().sort((a,b)=>descending?b.metrics[metric]-a.metrics[metric]:a.metrics[metric]-b.metrics[metric]).slice(0,14);const min=Math.min(...shown.map(x=>x.metrics[metric])),max=Math.max(...shown.map(x=>x.metrics[metric]));const lo=Math.min(0,min),hi=max===lo?lo+1:max*1.08;const h=60+shown.length*23;const scale=v=>260+(v-lo)/(hi-lo)*650;let svg=`<svg viewBox="0 0 960 ${h}" role="img" aria-label="${esc(metric)} by model on training-side validation"><text x="260" y="15" fill="#637080" font-size="11">${esc(document.querySelector('#metric').selectedOptions[0].textContent)} · Fold4 validation � best 14 configurations</text>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,x=scale(v);svg+=`<line x1="${x}" x2="${x}" y1="25" y2="${h-20}" stroke="#dce1dc"/><text x="${x}" y="${h-4}" text-anchor="middle" font-size="10" fill="#637080">${fmt(v,metric==='r'||metric==='hse_ts'?2:1)}</text>`;}shown.forEach((x,i)=>{const y=42+i*23;svg+=`<text x="245" y="${y+3}" text-anchor="end" font-size="10" fill="#162536">${esc(x.model)}</text><circle cx="${scale(x.metrics[metric])}" cy="${y}" r="${x.selected?5:3.5}" fill="${x.selected?'#49694e':'#7c8b96'}"><title>${esc(x.model)}: ${fmt(x.metrics[metric],3)}</title></circle>`;});document.querySelector('#plot').innerHTML=svg+'</svg>';}
async function load(){const r=await fetch('data.json',{cache:'no-store'});if(!r.ok)throw Error('Unable to load aggregate results');const d=await r.json();state.data=d;document.querySelector('#campaign').href=d.campaign_url;document.querySelector('#source').href=d.source_url;document.querySelector('#updated').textContent='Snapshot updated '+new Date(d.updated_at).toLocaleString();const ac=d.results.acquisition,em=d.results.embedding_audit;const stats=[['211 Å','Only solar input'],['4 / 3','Image history / delay'],[String(d.ledger.experiments.length),'Registered experiments']];if(ac)stats.push([String(ac.members),'Hash-verified original blocks']);if(em)stats.push(['832','Original image embeddings']);document.querySelector('#stats').innerHTML=stats.map(x=>`<div class="stat"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('');const rows=[];for(const [k,v]of Object.entries(d.results)){if(v.rows&&k!=='baseline'&&k!=='final_results')rows.push(...v.rows.map(x=>({...x,stage:v.stage,selected:v.selected?.model===x.model||v.best_ridge?.model===x.model})));}if(d.results.baseline)rows.unshift(...d.results.baseline.rows.filter(x=>x.model==='windnet_port_ensemble'));const seen=new Set();state.rows=rows.filter(x=>!seen.has(x.model)&&seen.add(x.model));document.querySelector('#comparison-scope').textContent=state.rows.length?'Training-side validation: original Folds1–3 fit; Fold4 evaluation. Every candidate uses the same row identities. These are development results.':'Original images acquired. Model comparison will appear when the registered fitting stage returns real results.';const fields=[['inputs','Identical information'],['development','Development boundary'],['final','Final evaluation'],['metrics','Paper metrics'],['success','Success criteria'],['stopping','Stopping rule']];document.querySelector('#protocol-content').innerHTML=fields.map(([key,title])=>`<div><h3>${title}</h3><p>${esc(d.protocol[key])}</p></div>`).join('');if(d.results.final_results){document.querySelector('#seal').textContent='Final evaluation completed · recipes frozen';document.querySelector('#seal-description').textContent='No further model adaptation follows test scoring.';document.querySelector('#final').hidden=false;document.querySelector('#final-verdict').textContent=d.results.final_results.verdict+' Previously viewed historical folds; no test-driven model changes.';const f=d.results.final_results;document.querySelector('#final-content').innerHTML='<div class=table-scroll><table><thead><tr><th>Frozen model / ablation</th><th>Mean RMSE (km/s)</th><th>Fisher r</th><th>Mean reduced chi-square</th><th>Mean HSE TS</th></tr></thead><tbody>'+f.rows.map(x=>'<tr class='+ (x.model===f.primary?'selected':'') +'><td>'+esc(x.model)+'</td><td>'+fmt(x.summary.mean_rmse)+'</td><td>'+fmt(x.summary.fisher_r,3)+'</td><td>'+fmt(x.summary.mean_chi2)+'</td><td>'+fmt(x.summary.mean_hse_ts,3)+'</td></tr>').join('')+'</tbody></table></div><p class=caption>Source: original five WindNet folds; same 2,198 test windows for every model. Mean-fold errors and Fisher-z correlation. Primary paired RMSE difference 95% interval: '+f.primary_uncertainty.mean_fold_rmse_delta_95.map(x=>fmt(x)).join(' to ')+' km/s. Conditional whole-block bootstrap; not adjusted for selection or prior exposure.</p>';}renderTrail();renderRows();}
document.querySelector('#status').addEventListener('change',renderTrail);document.querySelector('#metric').addEventListener('change',renderRows);document.querySelector('#stage').addEventListener('change',renderRows);load().catch(e=>{document.querySelector('#trail').textContent=e.message;});
